import os.path
import socket
import zipfile
import glob
import requests
import xmltodict

from pyexpat import ExpatError
from typing import Union, Optional
from xml.etree import ElementTree as Et

from requests import ReadTimeout, ConnectTimeout

from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper
from taf.rfrl.csv4all.resources.utilities.exceptions import WftConnectionError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class CSV4ALLWft:
    def __init__(self, location: Union[str, None] = None, build_suffix: Optional[str] = "A54",
                 test_packages: Union[str, list] = None):
        self.agent_dir = "/home/ute/.ute-ca/cache/bts"
        self.build_suffix = build_suffix
        self.target_sw_dict = {}
        self.test_packages = self._validate_testpackages(test_packages)
        self.access_key = "gKfr58ELsV5hdaBapwizQxhmBd9UR3Ndda0mbgvC"
        self.artifactory_key = "AKCp8oiHU5YPce4g24nY4H9XxoVHAVzcydFrggjst4Ym8FPW7jnEnLDyTDbkNk6ma5XV2NC95"
        self.location = self._validate_location(location)
        self.artifactory_url = self._get_correct_artifactory_url()
        self.wft_url = "https://wft.int.net.nokia.com:8091/api/v1/"
        self.fdsw_artifactory_urls = ['https://lterel.es-si-s3-z2.eecloud.nsn-net.net',
                                      'https://lterel.es-si-s3-z4.eecloud.nsn-net.net']
        self.knife_url = "https://es-si-s3-z2.eecloud.nsn-net.net/knife-results/"
        self.builds_to_download = set()
        self._download_failed = False

    def _get_wft_build_link(self, build_name: str) -> str:
        endpoint = self._get_endpoint(build_name)
        artifactory_list = self.fdsw_artifactory_urls if "FDSW" in build_name else []
        artifactory_list.append(self.artifactory_url)
        if "SBTS" in build_name and len(build_name.split("_")[4]) == 7:
            return f"{self.knife_url}{build_name.split('_')[4]}/{build_name}.zip"
        try:
            response = requests.get(url=self.wft_url + endpoint + self.access_key, timeout=120)
        except ReadTimeout as e:
            test_logger(e, "ERROR")
            raise WftConnectionError(f"Connection timeout to {self.wft_url}")
        if response.status_code != 200:
            raise WftConnectionError(f"Wrong request status: {response.content.decode('utf-8')}")

        for storage in response.json():
            for file_ in storage["storage"].get("storage-items", []):
                if f"{build_name}.zip" in file_["title"] and \
                        any(artifactory in file_.get("path") for artifactory in artifactory_list):
                    return file_.get("path")
        return ""

    @staticmethod
    def _get_sw_dir(sw_version: str, use_builds_storage: bool = True, download_path: str = None) -> str:
        if "FDSW" in sw_version:
            branch = sw_version.split("_")[2]
            build_type = "FDSW"
        else:
            branch = sw_version.split("_")[0]
            build_type = "SBTS"
        if use_builds_storage:
            return f'/mnt/UUF_SW/{build_type}/{branch}/'
        elif download_path is not None:
            return download_path
        return f'/home/ute/UUF_SW/{build_type}/{branch}/'

    @staticmethod
    def _is_file_size_correct(wft_file_size: str, file_path: str) -> bool:
        local_file_size = os.path.getsize(file_path)
        test_logger(f"Local file size: {local_file_size}", "DEBUG")
        test_logger(f"WFT file size: {wft_file_size}", "DEBUG")
        return int(wft_file_size) == int(local_file_size)

    @function_wrapper
    def download_build_from_wft(self, builds_to_download: Union[str, set], download_path: str = None,
                                test_package: Union[str, bool] = False, use_build_storage: bool = True,
                                download_candidate: bool = True):
        if not test_package and not download_candidate:
            raise ValueError(f"test_package and download_candidate both cannot be set on False")
        builds_to_download = self._get_modified_build_to_download(builds_to_download, test_package, download_candidate)
        for build in builds_to_download:
            download_dir = self._get_download_dir(build, use_build_storage, download_path)
            path_to_build = self.get_sw_path_from_agent_dir(build)
            if not path_to_build:
                path_to_build: list = glob.glob(f"{download_dir}/{build}.zip")
            if path_to_build and not self._download_failed:
                test_logger(f"File {build} is already downloaded")
                test_logger(f"Path: {path_to_build[0]}", "DEBUG")
                self.target_sw_dict[build] = path_to_build[0]
            else:
                self.trigger_sw_build_download(build, download_dir)

    @staticmethod
    def get_release_from_package(sw_build_path: str) -> str:
        sw_build = sw_build_path.split("/")[-1]
        if "SBTS00" not in sw_build:
            return sw_build.split("_")[0]
        try:
            with zipfile.ZipFile(sw_build_path, "r") as package:
                tree = Et.parse(package.open('sw_compatibility.xml'))
                for swm_type in tree.iter():
                    if 'SWRelease' in swm_type.tag:
                        return swm_type.text
                return ""
        except zipfile.BadZipfile as e:
            test_logger("Provided package is wrong, couldn't get sw release")
            test_logger(e, console=False)
            return "SBTS00"

    def get_sw_release(self, sw_build) -> str:
        if "SBTS00" not in sw_build:
            return sw_build.split("_")[0]
        try:
            response = requests.get(f'https://wft.int.net.nokia.com/ext/build_content/{sw_build}',
                                    headers={"X-JFrog-Art-Api": self.access_key}, timeout=120)
            if response.status_code != 200:
                raise WftConnectionError(f"Wrong request status: {response.content.decode('utf-8')}")
        except Exception as e:
            test_logger(e, "WARN")
            target_path = self.target_sw_dict.get(f"{sw_build}_release_BTSSM_downloadable_{self.build_suffix}", "")
            if target_path:
                return self.get_release_from_package(target_path)
            test_logger(f"Couldnt get sw release of {sw_build}", "ERROR")
            return "SBTS00"

        try:
            data = xmltodict.parse(response.content)
        except ExpatError as e:
            test_logger(e, console=False)
            data = None
        if data:
            try:
                for el in data['info']['content']['baseline']:
                    if el['@sc'] == 'NIDD_SBTS_NIDD':
                        return el['#text'].split("_")[0].replace("FSM3", '')
            except Exception as e:
                test_logger(e, "WARN")

        test_logger(f"Getting release for {sw_build} failed, SBTS00 will be used", "warn")
        return "SBTS00"

    def _get_download_dir(self, sw_build: str, use_build_storage: bool, download_path: str) -> str:
        download_dir = self._get_sw_dir(sw_build, use_build_storage, download_path)
        if 'burak' in download_dir:
            download_dir = os.path.join(download_dir, self._get_build_name_without_release_prefix(sw_build))
        if not os.path.exists(download_dir):
            os.makedirs(download_dir)

        return download_dir

    @staticmethod
    def _get_build_name_without_release_prefix(build_name):
        release_index = build_name.find('_release')
        if release_index != -1:
            return build_name[:release_index]
        return build_name

    def get_request_response(self, url: str) -> requests:
        test_logger(f"Getting build from: {url}", "DEBUG")
        headers = {'Authorization': f'Bearer {self.artifactory_key}'} if 'artifactory' in url else None
        response = requests.get(url=url, stream=True, timeout=120, headers=headers)
        if response.status_code != 200:
            raise WftConnectionError(f"Wrong request status: {response.content.decode('utf-8')}")
        return response

    def trigger_sw_build_download(self, build: str, download_dir: str):
        build_url = self._get_wft_build_link(build)
        if not build_url:
            raise Exception(f"Couldn't get url for {build}")
        wro_cache_build_url = self._replace_to_wroclaw_cache(build_url)
        build_file_name = build_url.split("/")[-1]
        path_to_build = os.path.join(download_dir, build_file_name)
        try:
            response = self.get_request_response(wro_cache_build_url)
        except ReadTimeout as e:
            test_logger(e, "ERROR")
            raise WftConnectionError(f"Connection timeout to {build_url}")
        except Exception as e:
            test_logger(e, "ERROR")
            response = self.get_request_response(build_url)
        test_logger(f"Downloading a {build_file_name} to {download_dir}")
        with open(path_to_build, "wb") as build_package:
            for chunk in response.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    build_package.write(chunk)

        if self._is_file_size_correct(response.headers.get('Content-Length'), path_to_build):
            test_logger(f"Build {build} downloaded correctly")
            self.target_sw_dict[build] = path_to_build
        else:
            raise Exception(f"Size of downloaded build {build} is incorrect")

    def _get_modified_build_to_download(self, builds_to_download: Union[str, set], test_package: bool,
                                        download_candidate: bool = True) -> set:
        if not isinstance(builds_to_download, set):
            builds_to_download = {builds_to_download}
        self.builds_to_download = builds_to_download
        if download_candidate:
            builds_to_download = {
                f"{build}_release_BTSSM_downloadable" if "FDSW" in build
                else f"{build}_release_BTSSM_downloadable_{self.build_suffix}"
                for build in builds_to_download}
        if test_package:
            if download_candidate:
                builds = {f"{build.replace(self.build_suffix, f'testpackage_{testpackage}_{self.build_suffix}')}"
                          for testpackage in self.test_packages for build in builds_to_download}
                builds_to_download.update(builds)
            else:
                builds_to_download = {f"{build}_release_BTSSM_downloadable_testpackage_" \
                                      f"{testpackage}_{self.build_suffix}"
                                      for testpackage in self.test_packages for build in builds_to_download}
        return builds_to_download

    @staticmethod
    def _get_endpoint(build_name):
        if "FDSW" in build_name:
            build_splited = build_name.split("_")
            if build_splited[3].isdigit():
                branch = build_splited[2]
            else:
                branch = "_".join(build_splited[2:4])
            url_build = build_name.replace("_release_BTSSM_downloadable", "")
        else:
            branch = build_name.split("_")[0]
            url_build = "_".join(build_name.split("_", 5)[:5])
        return f"{branch}/CI_ENB/builds/{url_build}/storages/results.json?access_key="

    def _get_correct_artifactory_url(self):
        artifactory_url = f"https://artifactory-{self.location}.int.net.nokia.com"
        return artifactory_url

    def _replace_to_wroclaw_cache(self, build_url: str) -> str:
        if self.artifactory_url in build_url:
            try:
                hostname_splitted = socket.gethostname().rstrip().split("-")
                location = hostname_splitted[1]
                organization = hostname_splitted[0]
                if location == "16" and organization.isdigit() and 0 <= int(organization) <= 10:
                    cache_url = f"https://{self.location}-" \
                                f"proxy-cache-vrf.wroclaw.nsn-rdnet.net"
                    build_url = build_url.replace(self.artifactory_url, cache_url)
            except IndexError:
                pass
        return build_url

    @staticmethod
    def _validate_location(location):
        if location in ["espoo1", "espoo2", "espoo3", "hz1", "bj1", "blr1", "ulm1", "fpark1"]:
            return location
        return "espoo2"

    @staticmethod
    def _validate_testpackages(test_packages):
        if not test_packages:
            test_packages = ["T1", "T2"]
        elif isinstance(test_packages, str):
            test_packages = [test_packages]
        return test_packages

    def get_sw_path_from_agent_dir(self, build: str):
        path_to_agent_build: list = []
        for build_name in self.builds_to_download:
            if build_name in build:
                path_to_agent_build = glob.glob(f"{self.agent_dir}/{build_name}/{build}.zip")
                break
        return path_to_agent_build

    def set_download_failed(self):
        self._download_failed = True
